#!/bin/sh
# Powermove: derives the vendored closure of upstream fx's src/ from the build
# graph, and refreshes src/ to exactly that closure (POWERMOVE.md, "Closure").
#
#   tools/derive-closure.sh <upstream fx clone> <commit>
#
# 1. Exports upstream's src/ at <commit> into a temporary folder.
# 2. Lays this tree over it: build.zig, build.zig.zon, include/, test-support/
#    and every file under src/ that carries a Powermove notice (ours).
# 3. Builds the `capi` and `fake-server` steps there with the pinned Zig and
#    a fresh local cache.
# 4. Reads the compile's cache manifest, which names every source file the
#    compiler read (Zig parses every file an @import names, used or not), and
#    writes those under src/ to tools/closure.txt.
# 5. Copies each listed upstream file into src/ (Powermove files are kept as
#    they are) and deletes from src/ every file the closure does not list.
#
# The tree is then built again by cargo (crate pm-aero-core) from src/ alone,
# which proves the closure is complete.
set -eu
[ $# -eq 2 ] || { echo "usage: $0 <upstream fx clone> <commit>" >&2; exit 2; }
upstream=$1
commit=$2
here=$(cd "$(dirname "$0")/.." && pwd)
version=$(awk '/^\[zig\]/{z=1;next} /^\[/{z=0} z && $1=="version"{gsub(/"/,"",$3); print $3; exit}' "$here/toolchain.toml")
zig_home=${PM_ZIG_HOME:-$HOME/.cache/powermove/zig}
zig="$zig_home/zig-aarch64-macos-$version/zig"
[ -x "$zig" ] || { echo "derive-closure: pinned Zig $version not found at $zig (run install-zig.sh)" >&2; exit 1; }

work=$(mktemp -d "${TMPDIR:-/tmp}/fx-closure.XXXXXX")
trap 'rm -rf "$work"' EXIT
git -C "$upstream" archive "$commit" src | tar -x -C "$work"
cp "$here/build.zig" "$here/build.zig.zon" "$work/"
cp -R "$here/include" "$here/test-support" "$work/"
ours=$(cd "$here" && grep -rl "Powermove notice" src || true)
for file in $ours; do
  mkdir -p "$work/$(dirname "$file")"
  cp "$here/$file" "$work/$file"
done

(cd "$work" && ZIG_GLOBAL_CACHE_DIR="$zig_home/zig-cache" "$zig" build capi fake-server \
  -Dtarget=aarch64-macos.13.0 --cache-dir "$work/.zig-cache" --prefix "$work/zig-out" --summary none)

manifest=$(grep -l -a 'src/capi_core_main.zig' "$work"/.zig-cache/h/* | head -n 1)
[ -n "$manifest" ] || { echo "derive-closure: no cache manifest names src/capi_core_main.zig" >&2; exit 1; }
grep -aoE 'src/[A-Za-z0-9_./-]+' "$manifest" | sort -u > "$work/closure.txt"
while read -r file; do
  [ -f "$work/$file" ] || { echo "derive-closure: manifest names $file, which the build tree lacks" >&2; exit 1; }
done < "$work/closure.txt"

# Upstream files only: ours are listed by their notice, not the manifest.
{
  echo "# Generated by tools/derive-closure.sh from upstream fx $commit: every"
  echo "# upstream file under src/ the capi build reads. Do not edit."
  for file in $(cat "$work/closure.txt"); do
    case " $(echo $ours) " in *" $file "*) ;; *) echo "$file" ;; esac
  done
} > "$here/tools/closure.txt"

# Refresh src/ to the closure.
for file in $(grep -v '^#' "$here/tools/closure.txt"); do
  mkdir -p "$here/$(dirname "$file")"
  cp "$work/$file" "$here/$file"
done
(cd "$here" && find src -type f) | while read -r file; do
  case " $(echo $ours) " in *" $file "*) continue ;; esac
  grep -qx "$file" "$here/tools/closure.txt" || rm "$here/$file"
done
find "$here/src" -type d -empty -delete
echo "closure: $(grep -vc '^#' "$here/tools/closure.txt") upstream files, $(echo $ours | wc -w | tr -d ' ') Powermove files"
